  apiKey: process.env.SECRET_KEY!,   // st_live_… from Dashboard → Settings → Secret keys
  baseUrl: 'https://strait.link',
});

// Create a link
const link = await links.createLink({
  slug: 'launch',
  longUrl: 'https://yourapp.com/launch',
  tags: ['campaign'],
});

// List / update / deactivate
await links.listLinks();
await links.updateLink('launch', { longUrl: 'https://yourapp.com/launch-v2' });
await links.deleteLink('launch');

// Send a conversion / revenue event (no publishable key needed server-side)
await links.sendEvent({ event: 'purchase', value: 49.99, currency: 'USD' });

// Name the tap it came from, when you know it (for example from a webhook)
await links.sendEvent({ event: 'purchase', value: 49.99, currency: 'USD', clickId });
```

On a server nothing is remembered for you: `sendEvent` passes `clickId` through only when you give it. Use a tap id you received, such as `clickId` from an `app.opened` or `install.matched` [webhook](https://straitlink.in/docs/webhooks/). The server keeps it only if it's a tap of your workspace; otherwise it drops the id and still records the event.

Failures throw a `StraitError` with `.status` and the parsed `.body`.

:::warn Keep the secret key on the server
The secret key can create and change links. Store it in an environment variable and never ship it in an app, a web page or a public repository. If it leaks, revoke it in the dashboard and create a new one.
:::

Every delivery carries this header:

```txt
X-Strait-Signature: t=<unix seconds>,v1=<signature>
```

`v1` is the hex HMAC-SHA256 of the string `<t>.<raw request body>` (the timestamp, a full stop, then the exact bytes of the body), keyed with your webhook's signing secret. To verify:

1. Read the **raw body** before parsing the JSON. Re-serialised JSON won't match.
2. Split the header on `,` and each part on the first `=` to get `t` and `v1`.
3. Refuse the request if `t` is more than **5 minutes** (300 seconds) away from your clock. That stops someone replaying an old delivery.
4. Compute the HMAC of `t`, `.` and the raw body with your secret, and compare it with `v1` in **constant time**.

Reply `401` when any step fails. Make sure your server's clock is set by NTP.

```ts title="Node / Express"
import { createHmac, timingSafeEqual } from 'node:crypto';
import express from 'express';

const TOLERANCE_SECONDS = 300;

export function verifyStraitSignature(secret: string, rawBody: Buffer, header: string | undefined): boolean {
  if (!header) return false;
  const parts = new Map(header.split(',').map((p) => {
    const i = p.indexOf('=');
    return [p.slice(0, i).trim(), p.slice(i + 1).trim()] as const;
  }));
  const t = parts.get('t') ?? '';
  const v1 = parts.get('v1') ?? '';
  if (!/^\d+$/.test(t) || !v1) return false;
  if (Math.abs(Date.now() / 1000 - Number(t)) > TOLERANCE_SECONDS) return false;
  const expected = createHmac('sha256', secret).update(`${t}.`).update(rawBody).digest('hex');
  const a = Buffer.from(expected);
  const b = Buffer.from(v1);
  return a.length === b.length && timingSafeEqual(a, b);
}

const app = express();

app.post('/webhooks/links', express.raw({ type: 'application/json' }), (req, res) => {
  if (!verifyStraitSignature(process.env.WEBHOOK_SECRET!, req.body, req.get('X-Strait-Signature'))) {
    return res.status(401).end();
  }
  const event = JSON.parse(req.body.toString('utf8'));
  // handle event.event / event.data …
  res.status(204).end();
});
```

