```go title="Go / net/http"
package webhooks

import (
	"crypto/hmac"
	"crypto/sha256"
	"encoding/hex"
	"io"
	"net/http"
	"os"
	"strconv"
	"strings"
	"time"
)

const toleranceSeconds = 300

func VerifyStraitSignature(secret string, body []byte, header string, now time.Time) bool {
	var t, v1 string
	for _, part := range strings.Split(header, ",") {
		k, v, _ := strings.Cut(strings.TrimSpace(part), "=")
		switch k {
		case "t":
			t = v
		case "v1":
			v1 = v
		}
	}
	ts, err := strconv.ParseInt(t, 10, 64)
	if err != nil || ts <= 0 || v1 == "" {
		return false
	}
	if d := now.Unix() - ts; d > toleranceSeconds || d < -toleranceSeconds {
		return false
	}
	mac := hmac.New(sha256.New, []byte(secret))
	mac.Write([]byte(t + "."))
	mac.Write(body)
	expected := hex.EncodeToString(mac.Sum(nil))
	return hmac.Equal([]byte(expected), []byte(v1))
}

func Handler(w http.ResponseWriter, r *http.Request) {
	body, err := io.ReadAll(io.LimitReader(r.Body, 1<<20))
	if err != nil || !VerifyStraitSignature(os.Getenv("WEBHOOK_SECRET"), body, r.Header.Get("X-Strait-Signature"), time.Now()) {
		http.Error(w, "invalid signature", http.StatusUnauthorized)
		return
	}
	// json.Unmarshal(body, &event); handle event.Event / event.Data …
	w.WriteHeader(http.StatusNoContent)
}
```

:::note Older receivers
We no longer send the first-format `X-Strait-Signature-Legacy` header (an HMAC of the body with no timestamp), because a copied delivery could be replayed with it. `X-Strait-Signature` is the only signature header. If your receiver still checks the old header, switch it to the code above.
:::

The code below splits the list into calls of 500 and retries a call on a network error, `429` or `5xx`. Retrying a whole call is safe: links created by the first try come back as `409` on the second, and the code counts those as done. Any other `4xx` stops the job, because sending it again won't help.

```js title="Node: batch-links.mjs"
// Node 18+ (global fetch). Creates any number of links, 500 per call; safe to re-run.
const API = 'https://strait.link/v1/links/batch';
const CHUNK = 500;

export async function createLinks(links, { secretKey = process.env.SECRET_KEY, fetchImpl = fetch, retryDelayMs = 1000 } = {}) {
  const created = [];
  const existing = [];
  const failed = [];
  for (let start = 0; start < links.length; start += CHUNK) {
    const chunk = links.slice(start, start + CHUNK);
    const data = await postWithRetry({ links: chunk }, secretKey, fetchImpl, retryDelayMs);
    for (const r of data.results) {
      const slug = chunk[r.index].slug;
      if (r.ok) created.push(r.link);
      else if (r.status === 409) existing.push(slug);
      else failed.push({ slug, status: r.status, error: r.error, reason: r.reason });
    }
  }
  return { created, existing, failed };
}

async function postWithRetry(payload, secretKey, fetchImpl, retryDelayMs, attempts = 4) {
  for (let attempt = 1; ; attempt++) {
    let res;
    try {
      res = await fetchImpl(API, {
        method: 'POST',
        headers: { Authorization: `Bearer ${secretKey}`, 'Content-Type': 'application/json' },
        body: JSON.stringify(payload),
      });
    } catch (err) {
      if (attempt >= attempts) throw err;
    }
    if (res?.ok) return res.json();
    if (res && res.status !== 429 && res.status < 500) throw new Error(`batch refused: HTTP ${res.status} ${await res.text()}`);
    if (attempt >= attempts) throw new Error(`batch failed after ${attempts} attempts (HTTP ${res?.status ?? 'network error'})`);
    await new Promise((resolve) => setTimeout(resolve, retryDelayMs * 2 ** (attempt - 1)));
  }
}
```

```python title="Python: batch_links.py"
import os
import time

import requests

API = "https://strait.link/v1/links/batch"
CHUNK = 500

def post_with_retry(payload, attempts=4):
    for attempt in range(1, attempts + 1):
        try:
            res = requests.post(
                API,
                headers={"Authorization": f"Bearer {os.environ['SECRET_KEY']}"},
                json=payload,
                timeout=60,
            )
        except requests.RequestException:
            if attempt == attempts:
                raise
        else:
            if res.ok:
                return res.json()
            if res.status_code != 429 and res.status_code < 500:
                raise RuntimeError(f"batch refused: HTTP {res.status_code} {res.text}")
            if attempt == attempts:
                raise RuntimeError(f"batch failed after {attempts} attempts (HTTP {res.status_code})")
        time.sleep(2 ** (attempt - 1))

def create_links(links):
    created, existing, failed = [], [], []
    for start in range(0, len(links), CHUNK):
        chunk = links[start:start + CHUNK]
        for r in post_with_retry({"links": chunk})["results"]:
            slug = chunk[r["index"]]["slug"]
            if r["ok"]:
                created.append(r["link"])
            elif r["status"] == 409:
                existing.append(slug)
            else:
                failed.append({"slug": slug, "status": r["status"], "error": r.get("error"), "reason": r.get("reason")})
    return created, existing, failed
