// Plain PHP with ext-curl. In Laravel, run createStraitLinks() from a queued job.

function postStraitBatch(array $payload, int $attempts = 4): array
{
    for ($attempt = 1; ; $attempt++) {
        $ch = curl_init('https://strait.link/v1/links/batch');
        curl_setopt_array($ch, [
            CURLOPT_CUSTOMREQUEST => 'POST',
            CURLOPT_RETURNTRANSFER => true,
            CURLOPT_TIMEOUT => 60,
            CURLOPT_HTTPHEADER => [
                'Authorization: Bearer ' . getenv('SECRET_KEY'),
                'Content-Type: application/json',
            ],
            CURLOPT_POSTFIELDS => json_encode($payload, JSON_THROW_ON_ERROR),
        ]);
        $response = curl_exec($ch);
        $status = curl_getinfo($ch, CURLINFO_RESPONSE_CODE);
        if ($response !== false && $status >= 200 && $status < 300) {
            return json_decode($response, true, 512, JSON_THROW_ON_ERROR);
        }
        if ($response !== false && $status !== 429 && $status < 500) {
            throw new RuntimeException("batch refused: HTTP $status $response");
        }
        if ($attempt >= $attempts) {
            throw new RuntimeException("batch failed after $attempts attempts (HTTP $status)");
        }
        sleep(2 ** ($attempt - 1));
    }
}

function createStraitLinks(array $links): array
{
    $created = $existing = $failed = [];
    foreach (array_chunk($links, 500) as $chunk) {
        foreach (postStraitBatch(['links' => $chunk])['results'] as $r) {
            $slug = $chunk[$r['index']]['slug'];
            if ($r['ok']) {
                $created[] = $r['link'];
            } elseif ($r['status'] === 409) {
                $existing[] = $slug;
            } else {
                $failed[] = ['slug' => $slug, 'status' => $r['status'], 'error' => $r['error'] ?? null];
            }
        }
    }
    return [$created, $existing, $failed];
}
