```java title="Java: StraitBatch.java"
import java.io.IOException;
import java.net.URI;
import java.net.http.HttpClient;
import java.net.http.HttpRequest;
import java.net.http.HttpResponse;
import java.time.Duration;

// Java 17+. Sends one call of up to 500 links (a JSON body you build with Jackson or Gson)
// and returns the response JSON. Split bigger lists into chunks of 500 and read each
// results[i]: ok, or status 409 (already exists), or another status (fix that item).
public final class StraitBatch {
    private static final HttpClient HTTP = HttpClient.newHttpClient();

    private StraitBatch() {}

    public static String postWithRetry(String linksJson) throws IOException, InterruptedException {
        int attempts = 4;
        for (int attempt = 1; ; attempt++) {
            HttpRequest request = HttpRequest.newBuilder(URI.create("https://strait.link/v1/links/batch"))
                .timeout(Duration.ofSeconds(60))
                .header("Authorization", "Bearer " + System.getenv("SECRET_KEY"))
                .header("Content-Type", "application/json")
                .POST(HttpRequest.BodyPublishers.ofString("{\"links\":" + linksJson + "}"))
                .build();
            int status = -1;
            try {
                HttpResponse<String> res = HTTP.send(request, HttpResponse.BodyHandlers.ofString());
                status = res.statusCode();
                if (status >= 200 && status < 300) return res.body();
                if (status != 429 && status < 500) throw new IllegalStateException("batch refused: HTTP " + status + " " + res.body());
            } catch (IOException e) {
                if (attempt >= attempts) throw e;
            }
            if (attempt >= attempts) throw new IllegalStateException("batch failed after " + attempts + " attempts (HTTP " + status + ")");
            Thread.sleep(1000L << (attempt - 1));
        }
    }
}
