```go title="Go: batch.go"
package straitlinks

import (
	"bytes"
	"encoding/json"
	"fmt"
	"io"
	"net/http"
	"os"
	"time"
)

type Link struct {
	Slug    string   `json:"slug"`
	LongURL string   `json:"longUrl"`
	Title   string   `json:"title,omitempty"`
	Tags    []string `json:"tags,omitempty"`
}

type Result struct {
	Index  int             `json:"index"`
	OK     bool            `json:"ok"`
	Status int             `json:"status"`
	Link   json.RawMessage `json:"link,omitempty"`
	Error  string          `json:"error,omitempty"`
}

// CreateLinks sends links in calls of 500. Results are in input order; status 409 means the slug already exists.
func CreateLinks(links []Link) ([]Result, error) {
	var all []Result
	for start := 0; start < len(links); start += 500 {
		end := min(start+500, len(links))
		results, err := postWithRetry(links[start:end], 4)
		if err != nil {
			return all, err
		}
		for i := range results {
			results[i].Index += start
		}
		all = append(all, results...)
	}
	return all, nil
}

func postWithRetry(chunk []Link, attempts int) ([]Result, error) {
	payload, err := json.Marshal(map[string][]Link{"links": chunk})
	if err != nil {
		return nil, err
	}
	client := &http.Client{Timeout: 60 * time.Second}
	for attempt := 1; ; attempt++ {
		req, err := http.NewRequest(http.MethodPost, "https://strait.link/v1/links/batch", bytes.NewReader(payload))
		if err != nil {
			return nil, err
		}
		req.Header.Set("Authorization", "Bearer "+os.Getenv("SECRET_KEY"))
		req.Header.Set("Content-Type", "application/json")
		status := 0
		res, err := client.Do(req)
		if err == nil {
			body, readErr := io.ReadAll(res.Body)
			res.Body.Close()
			status = res.StatusCode
			if readErr == nil && status >= 200 && status < 300 {
				var out struct {
					Results []Result `json:"results"`
				}
				if err := json.Unmarshal(body, &out); err != nil {
					return nil, err
				}
				return out.Results, nil
			}
			if status != 429 && status < 500 {
				return nil, fmt.Errorf("batch refused: HTTP %d %s", status, body)
			}
		}
		if attempt >= attempts {
			return nil, fmt.Errorf("batch failed after %d attempts (HTTP %d, %v)", attempts, status, err)
		}
		time.Sleep(time.Second << (attempt - 1))
	}
}
