```php title="PHP: StraitSignature.php"
<?php

function verify_strait_signature(string $secret, string $rawBody, ?string $header, ?int $now = null): bool
{
    if ($header === null || $header === '') {
        return false;
    }
    $parts = [];
    foreach (explode(',', $header) as $part) {
        $pair = explode('=', trim($part), 2);
        if (count($pair) === 2) {
            $parts[$pair[0]] = $pair[1];
        }
    }
    $t = $parts['t'] ?? '';
    $v1 = $parts['v1'] ?? '';
    if (preg_match('/^\d+$/D', $t) !== 1 || $v1 === '') {
        return false;
    }
    if (abs(($now ?? time()) - (int) $t) > 300) {
        return false;
    }
    $expected = hash_hmac('sha256', $t . '.' . $rawBody, $secret);
    return hash_equals($expected, $v1);
}
