```java title="Java: StraitSignature.java"
import java.nio.charset.StandardCharsets;
import java.security.GeneralSecurityException;
import java.security.MessageDigest;
import java.util.HashMap;
import java.util.HexFormat;
import java.util.Map;
import javax.crypto.Mac;
import javax.crypto.spec.SecretKeySpec;

public final class StraitSignature {
    private static final long TOLERANCE_SECONDS = 300;

    private StraitSignature() {}

    public static boolean verify(String secret, byte[] rawBody, String header) {
        return verify(secret, rawBody, header, System.currentTimeMillis() / 1000);
    }

    public static boolean verify(String secret, byte[] rawBody, String header, long nowSeconds) {
        if (header == null || header.isEmpty()) return false;
        Map<String, String> parts = new HashMap<>();
        for (String part : header.split(",")) {
            String[] kv = part.trim().split("=", 2);
            if (kv.length == 2) parts.put(kv[0], kv[1]);
        }
        String t = parts.getOrDefault("t", "");
        String v1 = parts.getOrDefault("v1", "");
        if (!t.matches("[0-9]{1,18}") || v1.isEmpty()) return false;
        if (Math.abs(nowSeconds - Long.parseLong(t)) > TOLERANCE_SECONDS) return false;
        try {
            Mac mac = Mac.getInstance("HmacSHA256");
            mac.init(new SecretKeySpec(secret.getBytes(StandardCharsets.UTF_8), "HmacSHA256"));
            mac.update((t + ".").getBytes(StandardCharsets.UTF_8));
            byte[] expected = HexFormat.of().formatHex(mac.doFinal(rawBody)).getBytes(StandardCharsets.UTF_8);
            return MessageDigest.isEqual(expected, v1.getBytes(StandardCharsets.UTF_8));
        } catch (GeneralSecurityException e) {
            throw new IllegalStateException(e);
        }
    }
}
