import os

import requests

def send_campaign(to: str, first_name: str, slug: str) -> dict:
    res = requests.post(
        f"https://graph.facebook.com/v23.0/{os.environ['PHONE_NUMBER_ID']}/messages",
        headers={"Authorization": f"Bearer {os.environ['WHATSAPP_TOKEN']}"},
        json={
            "messaging_product": "whatsapp",
            "recipient_type": "individual",
            "to": to,  # e.g. "919876543210"
            "type": "template",
            "template": {
                "name": "festive_sale",
                "language": {"code": "en"},
                "components": [
                    {"type": "body", "parameters": [{"type": "text", "text": first_name}]},
                    {"type": "button", "sub_type": "url", "index": "0", "parameters": [{"type": "text", "text": slug}]},
                ],
            },
        },
        timeout=30,
    )
    res.raise_for_status()
    return res.json()
