```php title="PHP: send-template.php"
<?php
// Plain PHP with ext-curl. In Laravel: Http::withToken($token)->post($url, $payload).

function sendCampaign(string $to, string $firstName, string $slug): array
{
    $payload = [
        'messaging_product' => 'whatsapp',
        'recipient_type' => 'individual',
        'to' => $to, // e.g. '919876543210'
        'type' => 'template',
        'template' => [
            'name' => 'festive_sale',
            'language' => ['code' => 'en'],
            'components' => [
                ['type' => 'body', 'parameters' => [['type' => 'text', 'text' => $firstName]]],
                ['type' => 'button', 'sub_type' => 'url', 'index' => '0', 'parameters' => [['type' => 'text', 'text' => $slug]]],
            ],
        ],
    ];
    $ch = curl_init('https://graph.facebook.com/v23.0/' . getenv('PHONE_NUMBER_ID') . '/messages');
    curl_setopt_array($ch, [
        CURLOPT_CUSTOMREQUEST => 'POST',
        CURLOPT_RETURNTRANSFER => true,
        CURLOPT_HTTPHEADER => [
            'Authorization: Bearer ' . getenv('WHATSAPP_TOKEN'),
            'Content-Type: application/json',
        ],
        CURLOPT_POSTFIELDS => json_encode($payload, JSON_THROW_ON_ERROR),
    ]);
    $response = curl_exec($ch);
    $status = curl_getinfo($ch, CURLINFO_RESPONSE_CODE);
    if ($response === false || $status >= 300) {
        throw new RuntimeException("WhatsApp send failed: HTTP $status $response");
    }
    return json_decode($response, true, 512, JSON_THROW_ON_ERROR);
}
```

**You should see:** a response with `"messages": [{"id": "wamid.…", "message_status": "accepted"}]`, and on your own opted-in test phone a message whose **Open the sale** button goes to `https://hilltop.strait.link/diwali`.
